const SHOP_KEY="japanTrip_shopping_v2",SHOP_DEFAULTS=[{"text": "משקפיים – JINS", "done": false, "area": "Shinjuku", "stores": [["JINS Flagship Store", "JINS Flagship Store Shinjuku Tokyo"], ["JINS Odakyu Ace", "JINS Shinjuku Odakyu Ace Store"], ["JINS Lumine Shinjuku", "JINS LUMINE Shinjuku Store"]]}, {"text": "נעלי ספורט", "done": false, "area": "Shinjuku", "stores": [["Alpen TOKYO", "Alpen TOKYO Shinjuku"], ["ABC-MART Shinjuku Honten", "ABC-MART Shinjuku Honten"], ["ABC-MART Grand Stage Lumine 2", "ABC-MART GRAND STAGE LUMINE Shinjuku LUMINE 2"]]}, {"text": "מכונת גילוח", "done": false, "area": "Shinjuku", "stores": [["Yodobashi Camera Shinjuku West", "Yodobashi Camera Shinjuku West Main Store"], ["BicCamera Shinjuku East", "BicCamera Shinjuku East Store"], ["Yodobashi Multimedia Shinjuku East", "Yodobashi Camera Multimedia Shinjuku East"]]}, {"text": "מכנסי ספורט", "done": false, "area": "Shinjuku", "stores": [["UNIQLO Shinjuku Flagship", "UNIQLO Shinjuku Honten"], ["UNIQLO MOVE Takashimaya", "UNIQLO MOVE Shinjuku Takashimaya"], ["GU BicCamera Shinjuku East", "GU Bic Camera Shinjuku East Exit Store"]]}];let shopItems=[];
function loadShopping(){try{shopItems=JSON.parse(localStorage.getItem(SHOP_KEY)||"null")||SHOP_DEFAULTS}catch(e){shopItems=SHOP_DEFAULTS}renderShopping()}
function saveShopping(){localStorage.setItem(SHOP_KEY,JSON.stringify(shopItems))}
function mapsUrl(q){return "https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(q)}
function esc(s){return String(s||"").replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;")}
function renderShopping(){const box=document.getElementById("shoppingList");if(!box)return;box.innerHTML="";shopItems.forEach((it,i)=>{const row=document.createElement("div");row.className="shop-item"+(it.done?" done":"");const stores=(it.stores||[]).map(s=>`<a class="shop-store-link" target="_blank" rel="noopener" href="${mapsUrl(s[1])}">${s[0]}<span>📍 מפה</span></a>`).join("");row.innerHTML=`<div class="shop-top"><input type="checkbox" ${it.done?"checked":""} onchange="toggleShop(${i})"><input class="shop-name" value="${esc(it.text)}" onchange="editShop(${i},'text',this.value)"><div class="shop-controls"><button onclick="moveShop(${i},-1)">↑</button><button onclick="moveShop(${i},1)">↓</button><button onclick="deleteShop(${i})">🗑</button></div></div><div class="shop-meta"><input placeholder="אזור / שכונה" value="${esc(it.area)}" onchange="editShop(${i},'area',this.value)"></div>${stores?'<div class="shop-store-title">חנויות מומלצות</div><div class="shop-stores">'+stores+'</div>':""}`;box.appendChild(row)})}
function addShopItem(){const x=document.getElementById("newShopItem");if(!x||!x.value.trim())return;shopItems.push({text:x.value.trim(),done:false,area:"",stores:[]});x.value="";saveShopping();renderShopping()}
function toggleShop(i){shopItems[i].done=!shopItems[i].done;saveShopping();renderShopping()}function editShop(i,k,v){shopItems[i][k]=v;saveShopping()}function deleteShop(i){shopItems.splice(i,1);saveShopping();renderShopping()}function moveShop(i,d){const j=i+d;if(j<0||j>=shopItems.length)return;[shopItems[i],shopItems[j]]=[shopItems[j],shopItems[i]];saveShopping();renderShopping()}
document.addEventListener("DOMContentLoaded",loadShopping);



const YEN_RATE_KEY="japanTrip_yen_per_ils_v1";
function loadYenRate(){
  try{
    const r=localStorage.getItem(YEN_RATE_KEY);
    if(r) document.getElementById("yenRate").value=r;
  }catch(e){}
}
function saveYenRate(){
  try{localStorage.setItem(YEN_RATE_KEY,document.getElementById("yenRate").value)}catch(e){}
}
function convertMoney(src){
  const rate=parseFloat(document.getElementById("yenRate").value)||0;
  const ils=document.getElementById("ilsAmount"),jpy=document.getElementById("jpyAmount"),res=document.getElementById("moneyResult");
  if(!rate){res.textContent="יש להזין שער המרה";return}
  if(src==="ils"){
    const v=parseFloat(ils.value);
    if(isNaN(v)){jpy.value="";res.textContent="הכנס סכום להמרה";return}
    const out=v*rate;jpy.value=Math.round(out);
    res.textContent=`₪${v.toLocaleString()} ≈ ¥${Math.round(out).toLocaleString()}`;
  }else{
    const v=parseFloat(jpy.value);
    if(isNaN(v)){ils.value="";res.textContent="הכנס סכום להמרה";return}
    const out=v/rate;ils.value=out.toFixed(2);
    res.textContent=`¥${Math.round(v).toLocaleString()} ≈ ₪${out.toFixed(2)}`;
  }
}
function openGoogleTranslate(){
  const q=(document.getElementById("translateText").value||"").trim();
  if(!q)return;
  window.open("https://translate.google.com/?sl=auto&tl=ja&text="+encodeURIComponent(q)+"&op=translate","_blank");
}
function setTranslate(t){document.getElementById("translateText").value=t}
function clearTranslate(){document.getElementById("translateText").value=""}
function speakJapanese(){
  const text=(document.getElementById("jpSpeakText").value||"").trim();
  if(!text)return;
  if(!("speechSynthesis" in window)){alert("מנוע דיבור אינו זמין בדפדפן הזה");return}
  speechSynthesis.cancel();
  const u=new SpeechSynthesisUtterance(text);u.lang="ja-JP";
  const voices=speechSynthesis.getVoices();
  const v=voices.find(x=>x.lang&&x.lang.toLowerCase().startsWith("ja"));
  if(v)u.voice=v;
  u.rate=0.88;speechSynthesis.speak(u);
}
document.addEventListener("DOMContentLoaded",loadYenRate);


const INDIVIDUAL_GUIDES={"Asakusa & Sensō-ji": ["זהו אחד האזורים הטובים בטוקיו לראות את החיבור בין Edo ההיסטורית לעיר המודרנית.", "Sensō-ji נחשב למקדש הבודהיסטי העתיק בטוקיו, והכניסה דרך Kaminarimon היא אחד המראות המזוהים עם העיר.", "Nakamise-dori מוביל אל המקדש עם חנויות קטנות, חטיפים ומזכרות מסורתיות; הרחובות הצדדיים לרוב מעניינים ושקטים יותר.", "כדאי להסתכל גם על הפגודה, השערים והמנהגים של המתפללים ולא להתייחס למקום רק כנקודת צילום.", "בשעות הבוקר המוקדמות המתחם רגוע בהרבה; בהמשך היום הרחוב נעשה צפוף ותוסס.", "אצלנו הוא משתלב מצוין עם Kappabashi, Ueno או הליכה לכיוון נהר Sumida, כך שאין צורך בנסיעה מיוחדת נוספת."], "Ueno & Ameyoko Market": ["Ueno נותן שילוב מוצלח של פארק גדול, מוזיאונים ואזור שוק עממי במרחק הליכה קצר.", "Ameyoko התפתח מאזור מסחר שלאחר המלחמה וכיום הוא רחוב צפוף של אוכל, בגדים, קוסמטיקה, תבלינים ודוכנים.", "החוויה כאן שונה מאוד מ-Ginza או Omotesando: פחות מלוטשת ויותר יומיומית ורועשת.", "גם בלי להיכנס למוזיאון, שווה לעבור דרך Ueno Park ואז לרדת לכיוון Ameyoko.", "זה מקום טוב לנשנושים ולקניות קטנות, אבל לא צריך לתכנן סביבו ארוחה גדולה.", "אצלנו הוא יושב טבעי לפני Akihabara, כך שהמעבר בין שני האזורים כמעט לא מבזבז זמן."], "Meiji Shrine": ["Meiji Jingu הוא מקדש שינטו המוקדש לקיסר Meiji ולקיסרית Shoken, דמויות מרכזיות בתקופת המודרניזציה של יפן.", "היער העצום סביבו נוצר מכ-100,000 עצים שנתרמו מרחבי יפן, ולכן מרגיש מפתיע בשקט שלו למרות Harajuku הסמוכה.", "ההליכה הארוכה מתחת לשערי Torii היא חלק מהחוויה ולא רק הדרך אל המבנה המרכזי.", "לעיתים ניתן לראות טקסי שינטו וחתונות מסורתיות, במיוחד בסופי שבוע, אך כמובן לא בונים על זה.", "הכניסה למתחם המרכזי חינם, והוא מתאים במיוחד לבוקר לפני שהרחובות המסחריים מתמלאים.", "אצלנו זה פתיח מצוין ליום Harajuku–Omotesando–Shibuya: עוברים משקט מסורתי לטוקיו המודרנית כמעט בלי נסיעה."], "Harajuku": ["Harajuku מזוהה עם אופנת רחוב, תרבות צעירה וסגנונות שהשפיעו הרבה מעבר ליפן.", "Takeshita Street הוא החלק הצבעוני והצפוף, עם חנויות קטנות, אופנה, מתוקים ומוצרים שמכוונים לקהל צעיר.", "כמה דקות משם האווירה משתנה לגמרי לכיוון Omotesando, עם אדריכלות ובוטיקים ברמה גבוהה.", "העניין עבורנו הוא בעיקר הניגוד בין שני העולמות, לאו דווקא קניות בחנויות עצמן.", "רוב החנויות נפתחות סביב 10:00–11:00, לכן אין טעם להגיע מוקדם לפני Meiji Shrine.", "מספיק בדרך כלל לעבור באזור שעה-שעתיים ולהמשיך ברגל לכיוון Omotesando ו-Shibuya."], "Omotesando": ["Omotesando היא אחת השדרות האלגנטיות בטוקיו ומוכרת בזכות שילוב של אופנה, אדריכלות וחנויות דגל.", "הבניינים עצמם מעניינים גם למי שלא מתכנן קניות, משום שמות אדריכליים גדולים תכננו כאן חזיתות ומתחמים.", "השדרה מספקת ניגוד חד ל-Takeshita Street הסמוכה: פחות כאוטית, יותר בוגרת ומסודרת.", "Omotesando Hills הוא אחד המתחמים הבולטים, אך אין חובה להקדיש זמן לקניון אם לא מתחשק.", "הדרך הנכונה עבורנו היא פשוט ללכת בה כחלק מהמסלול Harajuku→Shibuya ולבחור עצירות ספונטניות.", "כך מקבלים את החוויה בלי לבזבז זמן על נסיעה נפרדת או להפוך אותה ליעד של חצי יום."], "Shibuya": ["Shibuya הוא אחד המרכזים של התרבות העירונית המודרנית בטוקיו וה-Crossing הפך לסמל של הדינמיות של העיר.", "שווה לחצות את הצומת בעצמנו לפחות פעם אחת; מתוך זרם האנשים התחושה שונה לגמרי מצפייה מלמעלה.", "סביב התחנה נמצאים Hachiko, Center-Gai, קניות, מסעדות ובתי קפה, ולכן זה אזור שלם ולא רק מעבר חציה.", "בערב המסכים והאורות יוצרים את המראה האיקוני ביותר, בעוד שבשעות היום קל יותר להתמצא.", "לתצפית על המעבר אפשר להשתמש בנקודות באזור QFRONT/Starbucks או לבחור תצפית גבוהה יותר אם נרצה.", "אצלנו Shibuya מגיע אחרי Harajuku ו-Omotesando, ולכן המעבר בין האזורים טבעי וחוסך נסיעות."], "Tsukiji Outer Market": ["Tsukiji Outer Market נשאר מרכז אוכל פעיל גם אחרי שהשוק הסיטונאי עבר ל-Toyosu.", "הסמטאות מלאות בדגים, Tamagoyaki, אצות, תה, פירות, סכינים וכלי מטבח — הרבה מעבר לסושי ודג נא.", "עבורנו זה מתאים במיוחד כי אפשר לטעום דגים מבושלים ומאכלים קטנים בלי לבנות ארוחה סביב Seafood נא.", "השוק פעיל בעיקר בבוקר וחלק מהחנויות נסגרות מוקדם, ולכן 09:00 היא שעה טובה להתחיל.", "עדיף לטעום כמה דברים קטנים ממקומות שונים ולא לעמוד בתור ארוך רק כי דוכן מסוים מפורסם ברשת.", "משם קל להמשיך ל-Ginza, כך שהוא משתלב היטב ביום המרכזי שלנו בלי נסיעה מיותרת."], "Ginza": ["Ginza הוא רובע הקניות היוקרתי הקלאסי של טוקיו, אבל הוא מעניין גם בלי לקנות מותגי יוקרה.", "בתי הכלבו הוותיקים, חנויות הדגל והאדריכלות נותנים תמונה של הצד המלוטש והאלגנטי של העיר.", "Itoya מעניינת במיוחד לחובבי כלי כתיבה ועיצוב, וקומות המזון בבתי הכלבו הן חוויה בפני עצמה.", "בסופי שבוע חלק מ-Chuo-dori הופך לעיתים למרחב הולכי רגל, מה שהופך את השיטוט לנעים יותר.", "אין צורך לעבור בכל קניון; עדיף לבחור שתיים-שלוש נקודות וליהנות מהרחובות.", "אצלנו Ginza מגיעה אחרי Tsukiji, מרחק הליכה קצר, ולכן זו תוספת יעילה מאוד למסלול."], "Imperial Palace": ["הארמון הקיסרי יושב במקום שבו עמדה Edo Castle, ולכן המתחם מספר גם את סיפור טוקיו לפני שהפכה למטרופולין המודרני.", "רוב אזורי המגורים אינם פתוחים לשיטוט חופשי, ולכן החוויה היא בעיקר החפירים, חומות האבן, הגשרים והגנים.", "East Gardens מאפשרים לראות שרידים של הטירה ומרחב ירוק גדול בלב אזור העסקים.", "Nijubashi הוא אחד המראות המזוהים עם המתחם, אך אין צורך להקדיש זמן רב רק לצילום הגשר.", "הערך של הביקור הוא בעיקר בקנה המידה ובהיסטוריה, פחות בכניסה לארמון עצמו.", "אצלנו כדאי לשמור את הביקור קומפקטי ולהמשיך ברגל ל-Tokyo Station ו-Marunouchi."], "Tokyo Station & Marunouchi": ["Tokyo Station היא לא רק תחנת מעבר: חזית Marunouchi האדומה המשוחזרת היא אחד המבנים ההיסטוריים הבולטים במרכז העיר.", "בפנים נמצא עולם של מסעדות, חנויות ומעברים תת-קרקעיים, ובחוץ רובע עסקים מודרני מאוד.", "הניגוד בין התחנה ההיסטורית לגורדי השחקים של Marunouchi הוא חלק גדול מהעניין.", "כדאי לראות את החזית מכיוון Marunouchi ולא להסתפק במעבר בתוך התחנה.", "בערב התאורה יפה, וביום האזור מתחבר בקלות לארמון הקיסרי ול-Ginza.", "אצלנו זו עצירה טובה לסיום היום המרכזי ולא יעד שצריך להקדיש לו שעות."], "Shinjuku": ["Shinjuku הוא אחד מצמתי התחבורה והבילוי הגדולים בעולם ומרגיש כמעט כמו כמה שכונות שונות סביב תחנה אחת.", "במערב נמצאים גורדי השחקים ובניין ממשלת טוקיו; במזרח נמצאים Kabukicho, Golden Gai, Omoide Yokocho וקניות.", "הפער בין אזור העסקים המסודר לבין רחובות הלילה הצפופים הוא בדיוק מה שהופך את Shinjuku למעניין.", "התחנה עצומה ומורכבת, ולכן בחירת היציאה הנכונה חשובה יותר כאן מאשר ברוב טוקיו.", "בערב האזור מקבל את האופי המוכר של אורות ניאון, מסעדות וברים קטנים.", "אצלנו אפשר לשלב כאן גם את JINS ואת התצפית החינמית בבניין הממשלה וכך לקבל הרבה בלי נסיעות נוספות."], "Lake Ashi": ["Lake Ashi הוא אחד הנופים המזוהים ביותר עם Hakone ונוצר בתוך הקלדרה הגעשית של האזור.", "ביום בהיר אפשר לקבל שילוב יפה של האגם והר Fuji, אבל הראות משתנה במהירות ולכן מזג האוויר קובע את סדר היום.", "על שפת האגם נמצא Hakone Shrine ושער ה-Torii המפורסם במים.", "אפשר להסתפק בתצפיות והליכה קצרה או לשלב שיט אם הוא משתלב בזמנים ולא רק בשביל לסמן V.", "האזור נותן לנו שינוי משמעותי מהערים הגדולות: מים, הרים, יער ואוויר פתוח.", "אם Fuji גלוי בבוקר, נעדיף לנצל את הראות מיד ולא לדחות אותה לאחר הצהריים."], "Dotonbori": ["Dotonbori הוא הסמל של Osaka Minami ומרכז אוכל ובידור שהתפתח סביב התעלה כבר מהמאה ה-17.", "שלטי הענק, Glico Running Man והחזיתות התלת-ממדיות יוצרים את אחד מנופי הלילה המפורסמים ביפן.", "הרחוב מלא ב-Takoyaki, Okonomiyaki, Kushikatsu ומסעדות, ולכן עדיף להגיע כשיש תיאבון.", "ההיסטוריה של האזור קשורה לתיאטרון Kabuki ובידור, והאופי הרועש והצבעוני נשאר עד היום.", "בערב המקום במיטבו מבחינת אורות ואווירה; ביום נוח יותר להסתובב בלי צפיפות קיצונית.", "מאחר שאנחנו ישנים ב-Namba, אין צורך לדחוס אותו לשעה קבועה — אפשר לחזור אליו גם בערב נוסף."], "Kawaguchiko": ["Lake Kawaguchiko הוא אחד מחמשת אגמי Fuji ואחת הנקודות הנגישות והפופולריות ביותר לראות את ההר מקרוב.", "בנובמבר יש סיכוי לשילוב של Fuji מושלג ושלכת, מה שיכול להפוך אותו לאחד משיאי הטיול.", "החוויה תלויה מאוד בעננות: ביום צלול הנוף מרשים במיוחד, וביום סגור חלק גדול מהסיבה להגיע נעלם.", "יש כמה נקודות תצפית סביב האגם, ולכן אין צורך להיצמד לנקודה אחת אם התאורה או העננים פחות טובים.", "האזור דורש יותר זמן מהאקונה ולכן צריך להחליט לפי מזג האוויר ולא לנסות לדחוס הכול בכל מחיר.", "אצלנו הוא נשאר גמיש: אם התחזית טובה ניתן לו עדיפות, ואם לא — נשקיע יותר זמן ב-Hakone."], "Sannenzaka & Ninenzaka": ["רחובות היסטוריים עם בתי עץ, חנויות ותה.", "שתי הסמטאות המדורגות הן חלק מציר ההליכה ההיסטורי אל Kiyomizu-dera.", "בתי העץ והחנויות משמרים מראה קיוטואי מסורתי, עם קרמיקה, תה, ממתקים ועבודות יד.", "Yasaka Pagoda נמצאת באזור והופכת את המסלול בין Kiyomizu ל-Gion לאחד הקטעים המצולמים בעיר."], "Naramachi": ["Naramachi הוא רובע הסוחרים הישן של נארה, שהתפתח באזור שבו עמד בעבר מקדש Gango-ji.", "נשארו בו machiya מסורתיים שחלקם הפכו לבתי קפה, חנויות ומוזיאונים קטנים.", "הוא שקט יותר מאזור Nara Park ומתאים אם נרצה לראות צד עירוני-היסטורי של נארה ולא רק איילים ומקדשים."], "Arashiyama Bamboo Grove": ["Arashiyama הוא רובע טבע פופולרי במערב קיוטו, במיוחד בעונת השלכת של המחצית השנייה של נובמבר. יער הבמבוק הוא רק חלק מהאזור: סביבו נמצאים Tenryu-ji, גשר Togetsukyo, הנהר, חנויות ומסעדות. ככל שממשיכים צפונה לכיוון Okusaga האווירה נעשית כפרית ושקטה יותר.", "ה-Bamboo Grove הוא שביל קצר יחסית בתוך אזור Arashiyama ולא יער ענק שדורש שעות.", "הקטע המפורסם נמצא ליד Tenryu-ji; המשך צפונה מוביל לאזור Okusaga השקט יותר.", "בנובמבר העומס גבוה בגלל השלכת, ולכן אצלנו לא נחכה לצילום 'ריק' ונמשיך אם צפוף."], "Tenryu-ji": ["Tenryu-ji הוא מקדש זן מרכזי ב-Arashiyama והחשוב מבין מקדשי הזן באזור. הגן שלו תוכנן כך שההרים שמאחור משתלבים בנוף, והוא מתחבר בצורה טבעית למסלול לכיוון יער הבמבוק. זה מקום טוב לקבל גם מקדש וגם גן יפני בלי להוסיף נסיעה.", "Tenryu-ji נוסד במאה ה-14 והוא החשוב במקדשי הזן של אסכולת Rinzai בקיוטו.", "גן Sogenchi משתמש בהרי Arashiyama כרקע – דוגמה קלאסית ל-'borrowed scenery'.", "יציאה מהגן מובילה כמעט ישירות ל-Bamboo Grove, ולכן הוא משתלב בצורה יעילה מאוד במסלול."], "Kinkaku-ji": ["Kinkaku-ji, מקדש הזהב, הוא אחד הסמלים המפורסמים של קיוטו. הביתן המצופה זהב ניצב לצד בריכה ומשתקף במים, והביקור ממשיך במסלול מסודר דרך הגן. המקום פוטוגני מאוד אך יחסית קומפקטי.", "Kinkaku הוא חלק ממקדש Rokuon-ji; שתי הקומות העליונות של הביתן מצופות בעלי זהב.", "הביתן משתקף ב-Kyokochi Pond והגן תוכנן סביב נקודות מבט משתנות לאורך מסלול ההליכה.", "אי אפשר להיכנס לביתן עצמו, ולכן הביקור יחסית קצר ומתמקד בנוף ובגן."], "Tokyo Metropolitan Government Building Observatory": ["התצפית בבניין ממשלת טוקיו בשינג'וקו נותנת מבט רחב על המטרופולין מגובה של כ-200 מטר. היתרון הגדול מבחינתנו הוא שאין צורך לבנות את היום סביב הזמנה ל-Shibuya Sky, והיא משתלבת באזור שבו ממילא יש לנו קניות ו-JINS.", "המצפים נמצאים במגדלי בניין ממשלת טוקיו במערב Shinjuku בגובה של כ-200 מטר.", "הכניסה חינם, ולכן אפשר להחליט לפי הראות באותו יום בלי להפסיד כרטיס יקר.", "ביום צלול אפשר לראות מרחבים גדולים של טוקיו ולעיתים גם Fuji; שעות/סגירות משתנות ולכן בודקים באותו יום."], "Giōji Temple": ["Giōji הוא מקדש קטן ושקט באזור Okusaga, הידוע בגן טחב ירוק, במבוק ועצי מייפל. בנובמבר הניגוד בין הטחב הירוק לשלכת יכול להיות יפה במיוחד. האווירה כאן אינטימית בהרבה מה-Bamboo Grove המרכזי.", "Giōji הוא מקדש קטן המזוהה עם גן טחב, במבוק ומייפל באזור Saga/Okusaga.", "הוא קשור לסיפורה של Giō מתוך The Tale of the Heike, מה שמוסיף הקשר ספרותי למקום.", "בסתיו עלי המייפל מעל הטחב יוצרים צבעוניות חזקה, והקנה המידה הקטן שומר על אווירה אינטימית."], "Adashino Nenbutsu-ji": ["Adashino Nenbutsu-ji נמצא בחלק השקט יותר של Arashiyama/Okusaga וידוע באלפי פסלי אבן ובשביל במבוק קטן. הוא נותן שילוב של מקדש, אווירה היסטורית ובמבוק בלי העומס של היער הראשי.", "המקדש מזוהה עם אלפי פסלי אבן לזכר מתים שנקברו באזור Adashino לאורך מאות שנים.", "בשטח יש גם שביל במבוק קטן, ולכן הוא נותן חוויית במבוק שקטה יותר מה-Grove המרכזי.", "הוא נמצא עמוק יותר ב-Okusaga, באזור עם רחובות ישנים ואווירה כפרית יותר."], "Akihabara": ["Akihabara התחילה כרובע אלקטרוניקה והפכה למרכז ענק של אנימה, מנגה, משחקים ואספנות. לצד חנויות אלקטרוניקה גדולות יש בניינים שלמים עם משחקי רטרו, דמויות, קלפים ומוצרים יד שנייה. גם מי שלא חובב אנימה נהנה מהאורות ומהאווירה.", "השם Electric Town עדיין מתאים: לצד Yodobashi וחנויות אלקטרוניקה יש חנויות מתמחות בחלקים, מצלמות ומוצרים יד-שנייה.", "האזור מזוהה במיוחד עם תרבות otaku – אנימה, מנגה, משחקי ארקייד, figures וחנויות כמו Mandarake.", "אחר הצהריים והערב השלטים והמסכים הופכים את הרחובות לחלק מהחוויה, גם בלי קנייה."], "Shibuya Sky": ["Shibuya Sky נמצאת מעל Shibuya Scramble Square ונותנת תצפית פתוחה ומרשימה מעל Shibuya והעיר. זו חוויה אייקונית יותר מתצפית רגילה, אבל היא דורשת יותר תכנון בגלל כרטיסים ושעות מבוקשות.", "התצפית נמצאת בראש Shibuya Scramble Square, ישירות מעל אזור התחנה וה-Crossing.", "הייחוד הוא אזור גג פתוח ולא רק חלונות של מצפה סגור, ולכן מזג האוויר משפיע על החוויה.", "שעות שקיעה הן המבוקשות ביותר ולכן זו התצפית אצלנו שדורשת הכי הרבה תכנון מראש."], "Odawara": ["נקודת התחבורה המרכזית בדרך להאקונה. כאן נרד מהרכבת מטוקיו, נאסוף את הרכב, ובהמשך נחזיר אותו לפני העלייה ל-Shinkansen לקיוטו.", "Odawara היא שער התחבורה הנוח להאקונה: Shinkansen ורכבות מטוקיו נפגשים כאן עם קווי Hakone.", "בעיר נמצאת גם Odawara Castle, אך אצלנו התפקיד העיקרי שלה הוא איסוף/החזרת הרכב ולא יום טיול.", "היתרון הלוגיסטי הוא שלא צריך להיכנס עם רכב לטוקיו או להמשיך איתו לקיוטו."], "Hakone": ["אזור הררי ונופש הידוע במעיינות חמים, אגמים, טבע ותצפיות לפוג'י. מטרת העצירה היא להכניס לטיול יומיים של טבע ורוגע בין הערים הגדולות.", "Hakone נמצאת בתוך Fuji-Hakone-Izu National Park והיא אזור נופש ותיק של מעיינות חמים ונוף געשי.", "המסלול הקלאסי באזור מחבר Lake Ashi, Owakudani, Ropeway ורכבות ההרים, כך שהדרך עצמה היא חלק מהחוויה.", "הראות ל-Fuji אינה מובטחת; בבוקר ובימים קרים וצלולים הסיכוי בדרך כלל טוב יותר."], "Hakone Shrine": ["מקדש שינטו בתוך היער לצד Lake Ashi. אחד הסמלים שלו הוא שער Torii אדום שנמצא ממש על שפת האגם.", "המקדש נוסד באזור הר Hakone והיה במשך מאות שנים אתר פולחן חשוב לנוסעים בדרך Tokaido.", "Heiwa-no-Torii שעל שפת Lake Ashi הוא השער המצולם במים; התור לצילום יכול להיות ארוך.", "הדרך דרך יער הארזים והגרם העולה אל המקדש מעניינת לא פחות מה-Torii עצמו."], "Owakudani": ["Owakudani הוא עמק געשי פעיל ב-Hakone עם אדים, ריח גופרית ונוף דרמטי שנוצר בעקבות פעילות געשית. ביום בהיר אפשר לקבל מכאן גם תצפית לכיוון Fuji. הביצים השחורות המבושלות במים הגעשיים הן אחד הסמלים המקומיים.", "העמק נוצר באזור מכתש געשי והוא עדיין פעיל: רואים אדים ופתחי גופרית ממש מתחת לרכבל.", "Kuro-tamago הן ביצים שמבושלות במים הגאותרמיים וקליפתן משחירה בתהליך – הסמל הקולינרי של המקום.", "פעילות געשית או מזג אוויר עלולים לגרום להגבלות גישה, ולכן כדאי לבדוק מצב ביום הביקור."], "Hakone Ropeway": ["רכבל שעובר מעל האזור הגעשי ומחבר חלקים שונים של האקונה. מעבר לאמצעי תחבורה, הוא אטרקציה בזכות הנופים.", "הרכבל מחבר את Sounzan דרך Owakudani לכיוון Togendai שעל Lake Ashi.", "בקטע סביב Owakudani הקרוניות עוברות מעל הנוף הגעשי הפעיל; ביום צלול ניתן לראות גם Fuji.", "זהו חלק שימושי מה-Hakone Loop ולא אטרקציה שצריך לנסוע אליה בנפרד."], "Fuji / Kawaguchiko": ["אם מזג האוויר בהיר, נשתמש ברכב כדי לצאת לכיוון Lake Kawaguchiko וחמשת אגמי פוג'י. כאן פוג'י הוא ממש מרכז הנוף ולעיתים מקבלים תצפיות פתוחות ומרשימות במיוחד.", "Lake Kawaguchiko הוא הנגיש ביותר מבין Fuji Five Lakes ומהווה בסיס מרכזי לתצפיות על ההר.", "הצד הצפוני של האגם ידוע בזוויות שבהן Fuji משתקף או מופיע מאחורי האגם; בנובמבר מתווספת שלכת.", "כיוון שההר יכול להיעלם בעננים תוך זמן קצר, נעדיף תצפית טובה ברגע שהיא מופיעה ולא 'לשמור אותה לאחר כך'."], "Gion": ["Gion הוא רובע מסורתי המזוהה עם בתי תה, machiya מעץ ותרבות הגיישות של קיוטו. הרחובות סביב Hanamikoji ו-Shirakawa נותנים תחושה היסטורית, במיוחד לקראת ערב, אבל זה עדיין אזור מגורים ועבודה ולא אתר שעשועים.", "Gion התפתח סביב Yasaka Shrine כרובע בידור מסורתי, ובחלקיו עדיין פועלים ochaya שבהם עובדות geiko ו-maiko.", "Hanamikoji ו-Shirakawa הם הרחובות המזוהים ביותר עם בתי machiya מעץ, אך חלק מהסמטאות פרטיות ואסור לצלם בהן.", "לקראת ערב הפנסים והמסעדות יוצרים את האווירה הטובה ביותר; חשוב לא לרדוף או לצלם geiko/maiko ללא רשות."], "Kiyomizu-dera": ["Kiyomizu-dera הוא אחד המקדשים החשובים והיפים בקיוטו, בנוי על מורדות Higashiyama ומציע תצפית רחבה על העיר. הדרך אליו דרך Ninenzaka ו-Sannenzaka היא חלק מרכזי מהחוויה, עם בתי עץ מסורתיים, בתי תה וחנויות.", "המקדש נוסד במאה ה-8 ושמו קשור למים הצלולים של Otowa Waterfall שמתחת למתחם.", "הבמה הגדולה של האולם הראשי בנויה מעץ על צלע ההר וממנה נשקף Higashiyama והעיר.", "הוא חלק מאתרי המורשת העולמית של קיוטו, וההליכה אליו דרך Sannenzaka/Ninenzaka היא חלק מהביקור."], "Higashiyama": ["האזור ההיסטורי שסביב Kiyomizu-dera. רחובות Ninenzaka ו-Sannenzaka מלאים בבתי עץ, תה, קרמיקה, חנויות מסורתיות וממתקים.", "Higashiyama שומר על אחד המרקמים ההיסטוריים המזוהים ביותר עם קיוטו: סמטאות, machiya, מקדשים וחנויות מלאכה.", "Yasaka Pagoda היא נקודת הציון הבולטת בין Kiyomizu ל-Gion.", "האזור מזוהה גם עם Kiyomizu-yaki, מסורת הקרמיקה שהתפתחה סביב המקדשים."], "Pontocho": ["סמטה צרה ומפורסמת ליד נהר Kamo, מלאה במסעדות וברים קטנים. מקום מצוין לסיים בו ערב בקיוטו.", "Pontocho היא סמטה צרה המקבילה לנהר Kamo בין Shijo ל-Sanjo, ומזוהה עם מסעדות ובתי אוכל קטנים.", "בקיץ חלק מהמסעדות מפעילות מרפסות kawayuka מעל הנהר; בנובמבר עיקר החוויה היא הסמטה והאורות בערב.", "היא נמצאת מול Gion מעבר לנהר ולכן מתאימה במיוחד לסיום יום באזור המזרחי."], "Arashiyama": ["אזור במערב קיוטו הידוע ב-Bamboo Grove, מקדשים, נהר והרים. בנובמבר צבעי הסתיו יכולים להפוך אותו ליפה במיוחד. מומלץ להגיע מוקדם.", "Togetsukyo Bridge הוא המרכז הגאוגרפי של Arashiyama, עם הנהר וההרים כרקע.", "Tenryu-ji הוא אתר מורשת עולמית וה-Bamboo Grove מתחיל ממש בסביבתו, כך שאפשר לחבר אותם ברגל.", "בנובמבר האזור פופולרי במיוחד בגלל השלכת; המשך צפונה ל-Okusaga נותן צד שקט יותר."], "Nishiki Market": ["Nishiki Market הוא רחוב שוק צר במרכז קיוטו עם יותר ממאה חנויות ומסעדות, ולכן זכה לכינוי 'המטבח של קיוטו'. הרבה חנויות מתמחות במוצר אחד בלבד – תה, חמוצים, סכינים, ממתקים, דגים, טופו או תוצרת מקומית – וחלקן פועלות באותה משפחה במשך דורות.", "השוק משתרע לאורך כחמישה בלוקים במרכז קיוטו ופועל כבר מאות שנים כמרכז למוצרי מזון מקומיים.", "מומלץ לחפש מאכלים המזוהים עם קיוטו כמו tsukemono, yuba, תה וממתקים, ולא להתייחס אליו רק כשוק דגים.", "השוק צר מאוד; אכילה תוך כדי הליכה אינה מקובלת בחלק מהמקומות ועדיף לאכול ליד הדוכן שממנו קונים."], "Fushimi Inari": ["Fushimi Inari הוא מקדש שינטו חשוב בדרום קיוטו ומפורסם בזכות אלפי שערי Torii אדומים שמטפסים לאורך שבילי הר Inari. המקדש מוקדש לאינארי, אל הקשור לאורז ולשגשוג, ולכן ברחבי המתחם תראו גם פסלי שועלים, הנחשבים לשליחיו. שמות התורמים מופיעים על גב שערי ה-Torii.", "Fushimi Inari Taisha הוא המקדש הראשי של אלפי מקדשי Inari ביפן.", "אלפי שערי torii נתרמו בעיקר על ידי עסקים ואנשים פרטיים; שמות התורמים מופיעים בצד האחורי.", "המסלול המלא עולה להר Inari, אבל אין צורך להשלים אותו כדי לחוות את Senbon Torii; מוקדם בבוקר העומס נמוך משמעותית."], "Nara Park": ["פארק Nara הוא מרחב ירוק גדול שבו מסתובבים איילי sika בחופשיות, והם הפכו לסמל העיר. הפארק מחבר בין כמה מהאתרים החשובים בנארה ולכן האיילים הם חלק מהדרך ולא האטרקציה היחידה.", "הפארק משתרע על כ-660 הקטר ומחבר את Todaiji, Kasuga Taisha ואתרים נוספים.", "איילי sika נחשבים במסורת המקומית לשליחים קדושים; כיום הם מוגנים כסמל טבעי של נארה.", "אפשר לקנות shika-senbei להאכלה, אבל האיילים עלולים להיות נמרצים סביב אוכל ולכן לא מחזיקים שקית פתוחה זמן רב."], "Tōdai-ji": ["Tōdai-ji הוא אחד המקדשים הבודהיסטיים החשובים ביפן והסיבה ההיסטורית המרכזית להגיע לנארה. אולם Daibutsuden העצום מכיל פסל בודהה ברונזה ענק, והמבנה עצמו מרשים מאוד בקנה המידה שלו.", "Daibutsuden מכיל את ה-Daibutsu, פסל בודהה ברונזה בגובה כ-15 מטר.", "הכניסה דרך Nandaimon עוברת ליד שני פסלי שומר Nio עצומים, כך שכדאי לא למהר ישר לאולם הגדול.", "מאחורי המקדש Nigatsudo נותן תצפית יפה על נארה ומשתלב בהליכה לכיוון Kasuga Taisha."], "Kuromon Market": ["Kuromon הוא שוק מקורה באוסקה באורך של כ-600 מטר ובו בערך 150 חנויות. מלבד דגים ופירות ים יש גם בשר, פירות, ממתקים, כלי בית ודוכני אוכל. הוא מתאים מאוד לטעימות ולשיטוט ולא רק לארוחה.", "השוק באורך כ-580 מטר ובו קרוב ל-170 חנויות; הוא שימש במשך שנים גם כמקום קנייה לשפים ומסעדנים מקומיים.", "השם 'Kuromon' – שער שחור – הגיע משער של מקדש Enmyoji שהיה באזור.", "מעבר לפירות ים יש Wagyu, פירות, ממתקים ומוצרי מזון, ולכן הוא מתאים לנו גם בלי להתמקד בדג נא."], "Namba": ["Namba הוא מרכז התחבורה, הקניות והבילויים של דרום Osaka. Dotonbori, Shinsaibashi ו-Kuromon נמצאים כולם בטווח הליכה, ולכן זה אזור מצוין לרכז בו ערב של אוכל ושיטוט.", "Namba היא אחד מצמתי התחבורה המרכזיים בדרום אוסקה ומחברת Osaka Metro, Nankai, Kintetsu/Hanshin ו-JR Namba.", "Dotonbori, Shinsaibashi ו-Kuromon נמצאים בטווח הליכה, ולכן האזור נשאר פעיל גם אחרי שעות האטרקציות.", "Nankai Namba היא גם נקודת יציאה נוחה לכיוון Kansai Airport, אף שבטיול שלנו הטיסה היא מטוקיו."], "Osaka Castle": ["טירת Osaka נבנתה לראשונה בסוף המאה ה-16, נהרסה ונבנתה מחדש כמה פעמים, והמבנה הנוכחי הוא שחזור מודרני. בפנים יש מוזיאון, אבל סביב הטירה יש פארק גדול, חפירים וגנים, ולכן אפשר ליהנות מאוד גם בלי להיכנס.", "Toyotomi Hideyoshi החל לבנות את הטירה ב-1583 כחלק מאיחוד יפן.", "מגדל הטירה הנוכחי הוא שחזור מהמאה ה-20 ובתוכו מוזיאון; החומות, החפירים והפארק הם שרידים/שחזורים של מתחם גדול בהרבה.", "אם לא נרצה מוזיאון היסטורי, אפשר להסתפק בפארק ובתצפיות החיצוניות ולחסוך זמן."], "Umeda": ["מרכז מודרני של אוסקה עם גורדי שחקים, קניונים ותחנות רכבת ענקיות. אפשר לשלב תצפית גבוהה על העיר.", "Umeda הוא המרכז הצפוני של Osaka סביב Osaka/Umeda Stations, עם רשת גדולה של קניונים ומעברים תת-קרקעיים.", "Umeda Sky Building מוכר בזכות Floating Garden Observatory שמחבר את שני מגדלי המבנה בחלק העליון.", "האזור שונה מ-Namba: מודרני ועסקי יותר ופחות ממוקד באוכל רחוב וחיי לילה."], "Shinsaibashi": ["Shinsaibashi הוא אחד מאזורי הקניות המרכזיים של Osaka, עם רחוב מקורה ארוך שמוביל כמעט ישירות ל-Dotonbori. יש בו שילוב של מותגים בינלאומיים, אופנה יפנית, קוסמטיקה ובתי קפה.", "Shinsaibashi-suji הוא רחוב קניות מקורה באורך של מאות מטרים שממשיך צפונה מ-Dotonbori.", "באזור נמצאים מותגים בינלאומיים לצד חנויות יפניות, קוסמטיקה ו-Amerikamura הסמוכה.", "מכיוון שהוא מחובר כמעט ברצף ל-Namba/Dotonbori, אין צורך להקצות לו נסיעה או יום נפרד."], "JINS Shinjuku 👓": ["מטרה: לעשות משקפיים בטוקיו. מומלץ לשלב ביום שינג׳וקו ולהקצות 1.5–2 שעות לבדיקה, מסגרת ועדשות. אם המשקפיים אינם מוכנים במקום, להשאיר חלון איסוף בהמשך השהות בטוקיו.", "JINS היא רשת אופטיקה יפנית שבה מחיר המסגרת כולל בדרך כלל עדשות סטנדרטיות, עם תוספות לפי סוג העדשה.", "בדיקת ראייה יכולה להתבצע בחנות, והכנה של מרשם פשוט עשויה להיות מהירה; עדשות מיוחדות עלולות לדרוש יותר זמן.", "לכן נכון לבצע את ההזמנה בתחילת טוקיו ולהשאיר את הימים האחרונים כאפשרות לאיסוף."], "JINS Shinjuku": ["JINS היא רשת משקפיים יפנית גדולה שבה ניתן לבחור מסגרת, לבצע בדיקת ראייה ולהזמין עדשות במקום. המטרה שלנו היא לעשות זאת בתחילת השהות בטוקיו כדי להשאיר זמן לאיסוף.", "JINS היא רשת אופטיקה יפנית שבה אפשר לבחור מסגרת, לבצע בדיקת ראייה ולהזמין עדשות באותו תהליך.", "מרשמים פשוטים יכולים לעיתים להיות מוכנים במהירות, אך עדשות מיוחדות או מלאי חסר עשויים לדרוש ימים.", "אצלנו עדיף לבצע בתחילת השהות כדי שהחזרה לטוקיו בסוף הטיול תשמש רשת ביטחון לאיסוף."], "Hakone Open-Air Museum": ["המוזיאון הפתוח של Hakone מציג פסלים ואמנות בתוך פארק גדול על רקע ההרים, לצד גלריות מקורות. זה מקום שמרגיש יותר כמו טיול בפארק אמנות מאשר ביקור במוזיאון רגיל.", "זה היה המוזיאון הפתוח הראשון לפיסול ביפן, שנפתח ב-1969 בתוך Fuji-Hakone-Izu National Park.", "בשטח של כ-70,000 מ״ר מוצגות כ-100–120 יצירות חוץ של אמנים מודרניים, ולמוזיאון גם אוסף של יותר מ-300 עבודות Picasso.", "יש גם Symphonic Sculpture מזכוכית צבעונית ו-footbath ממי מעיינות חמים; שעות הפתיחה הן 09:00–17:00."], "Kawaguchiko / Fuji": ["נשאר בתכנון. מקום הלינה באזור האקונה/פוג׳י עדיין לא נקבע, ולכן המסלול נשאר גמיש בין Hakone לבין Kawaguchiko.", "Lake Kawaguchiko הוא אחד מ-Fuji Five Lakes ומוכר במיוחד בזכות תצפיות פתוחות על Fuji.", "בנובמבר האזור מושך מבקרים גם בשלכת; שילוב של מייפל אדום, אגם ו-Fuji אפשרי כשהראות טובה.", "מקום הלינה עדיין לא סגור ולכן נשמור אותו כחלופה גמישה מול Hakone לפי תחזית הראות."], "Kinkaku-ji · מקדש הזהב": ["נוסף למסלול קיוטו כאטרקציית חובה, עם שילוב לפי הסדר הגאוגרפי של אותו יום.", "Kinkaku, הביתן המוזהב, הוא חלק מ-Rokuon-ji ואתר מורשת עולמית.", "שתי הקומות העליונות מצופות בעלי זהב והמבנה תוכנן כך שישתקף ב-Kyokochi Pond.", "המסלול במקום קומפקטי וחד-כיווני יחסית; עיקר הביקור הוא הביתן, הבריכה והגן ולא כניסה לתוך המבנה."], "teamLab Biovortex Kyoto": ["teamLab Biovortex Kyoto נפתח ב-2025 כמתחם אמנות דיגיטלית גדול וקבוע בקיוטו.", "העבודות הן immersive ואינטראקטיביות: אור, תנועה וחללים משתנים מגיבים לנוכחות המבקרים.", "זו חוויה מודרנית מאוד שמאזנת אצלנו את ריבוי המקדשים והאתרים ההיסטוריים בקיוטו; היא אינה זהה לחוויית המים היחפה של Planets Tokyo."], "Gyukatsu Motomura Shinjuku": ["Gyukatsu – בקר מצופה ומטוגן שממשיכים לצלות על אבן חמה.", "המנה המרכזית היא gyukatsu: בקר בציפוי פריך שמוגש medium-rare וממשיכים לצלות בעצמנו על אבן חמה.", "הסגנון מאפשר לשלוט במידת העשייה של כל חתיכה; מגישים בדרך כלל עם אורז, כרוב, רטבים ומלח.", "לרשת כמה סניפים באזור Shinjuku; הסניף הראשי פתוח לפי האתר הרשמי 11:00–22:00, כך שקל לשלב ביום Shinjuku."], "Uobei Shibuya Dogenzaka": ["סושי בהזמנה ממסך; אפשר לבחור גם מנות מבושלות.", "Uobei הוא סושי מהיר שבו מזמינים במסך והמנות מגיעות ישירות במסילה לשולחן.", "הפורמט פשוט וזול יחסית ומתאים לטעימה של מנות קטנות בלי ארוחה רשמית.", "יש גם פריטים מבושלים ולא-נאים, ולכן הוא מתאים לנו יותר מסושייה שמבוססת כמעט כולה על sashimi."], "Afuri Harajuku": ["AFURI מזוהה במיוחד עם Yuzu Shio Ramen – מרק קל וארומטי עם הדר yuzu.", "זה סגנון פחות כבד מ-tonkotsu ramen, ולכן מתאים לעצירה באמצע יום הליכה ב-Harajuku/Omotesando.", "השם AFURI מתייחס להר Afuri בקנאגאווה, והמותג מדגיש שימוש במים ומרכיבים ליצירת מרק נקי."], "Katsukura Kyoto": ["Tonkatsu יפני – בשר מצופה ומטוגן עם אורז וכרוב.", "Katsukura היא רשת שנולדה בקיוטו ומתמחה ב-tonkatsu – חזיר מצופה panko ומטוגן.", "אחד המאפיינים הוא טחינת שומשום בקערה קטנה והכנת הרוטב בשולחן.", "הארוחה כוללת בדרך כלל אורז, כרוב ומרק לצד הקאטסו, ולכן זו אופציה טובה למי שרוצה אוכל יפני מבושל ולא דג נא."], "Musashi Sushi Kyoto Station": ["סושי נגיש ליד התחנה, כולל אפשרויות מבושלות.", "Musashi Sushi היא רשת kaiten-sushi מקיוטו, כלומר מנות קטנות בסגנון conveyor-belt sushi.", "היתרון עבורנו הוא שאפשר לבחור מנה-מנה ולשלב דגים מבושלים, tamago ופריטים שאינם נאים.", "המיקום ליד Kyoto Station הופך אותה לאופציה תפעולית טובה ביום הגעה/עזיבה ולא למסעדה שצריך לחצות את העיר בשבילה."], "Mizuno Osaka": ["Mizuno היא מסעדת okonomiyaki ותיקה באזור Dotonbori ומזוהה עם הסגנון האוסאקאי שבו הבלילה והמרכיבים מעורבבים יחד.", "המנות נצלות על teppan וה-okonomiyaki מוגש עם רוטב, מיונז ותוספות.", "המיקום בתוך Dotonbori הופך אותה לאפשרות טבעית בערב באזור, אבל אם התור ארוך אין סיבה לבזבז זמן כי יש הרבה חלופות טובות בסביבה."], "551 Horai": ["רשת אוסקאית מפורסמת בלחמניות מאודות עם בשר.", "551 HORAI היא רשת אוסקאית מפורסמת במיוחד ב-butaman – לחמניות מאודות ממולאות חזיר.", "הייצור והמכירה מתמקדים באזור Kansai, ולכן היא מרגישה יותר כמו טעימה מקומית מאשר רשת שאפשר למצוא בכל יפן.", "זו עצירת snack נוחה ולא ארוחה שצריך לבנות סביבה; סניפים נמצאים בתחנות ובמרכזי קניות באוסקה."], "Kaminarimon": ["שער הרעם האדום הענק הוא הסמל של Asakusa והכניסה המפורסמת ל-Sensō-ji. הפנס האדום הגדול במרכז הוא אחת מתמונות החובה של טוקיו.", "Kaminarimon הוא השער החיצוני של Sensō-ji והסמל המזוהה ביותר עם Asakusa.", "הפנס האדום הענק במרכז נושא את שם השער; משני הצדדים ניצבים פסלים של אלי הרוח והרעם.", "מיד אחריו מתחיל Nakamise, ולכן אין צורך לתכנן אותו כעצירה נפרדת – הוא פתיחת מסלול Sensō-ji."], "Nakamise": ["רחוב קניות מסורתי באורך של כמה מאות מטרים המוביל מ-Kaminarimon אל Sensō-ji. הדוכנים מוכרים ממתקים יפניים, מניפות, מזכרות, עבודות יד וחטיפים.", "Nakamise-dori נמתח בין Kaminarimon לשער Hozomon ומלווה את הדרך ל-Sensō-ji כבר מאות שנים.", "החנויות הקטנות מוכרות wagashi, senbei, מניפות, עבודות יד ומזכרות מסורתיות.", "הרחוב עמוס בשעות היום; מוקדם אפשר לראות את תריסי החנויות המצוירים גם לפני שהכול נפתח."], "Sensō-ji": ["סנסו-ג׳י הוא המקדש הבודהיסטי העתיק ביותר בטוקיו ואחד הסמלים של Asakusa. הדרך אליו דרך Kaminarimon ו-Nakamise היא חלק מהחוויה, לא רק אמצעי להגיע למקדש: עוברים בין שערים, דוכנים, ממתקים מסורתיים וחנויות קטנות שממחישות צד ישן יותר של טוקיו. המתחם עצמו גדול וכולל את האולם המרכזי, פגודה וחצרות פתוחות.", "לפי המסורת, ראשית המקדש בשנת 628 סביב פסל Kannon שנמשה מנהר Sumida; זהו המקדש העתיק בטוקיו.", "האולם הראשי, Hozomon והפגודה יוצרים מתחם גדול בהרבה מהצילום המפורסם של Kaminarimon.", "אפשר לנסות omikuji ולהבחין במנהג טיהור בעשן הקטורת מול האולם הראשי."], "Ueno": ["Ueno משלב פארק עירוני גדול, מוזיאונים ושוק רחוב עממי. פארק Ueno נמצא ליד כמה מהמוזיאונים החשובים בעיר, וממש בסמוך נמצא Ameyoko, כך שקל לעבור מטבע ותרבות לשוק, אוכל וקניות באותו אזור.", "Ueno Park הוקם במאה ה-19 והוא אחד הפארקים הציבוריים הוותיקים ביפן.", "בתוך וסביב הפארק נמצאים Tokyo National Museum, National Museum of Nature and Science, Ueno Zoo ומקדשים.", "מדרום לתחנה מתחיל Ameyoko, כך שהאזור מחבר תרבות ומוזיאונים עם שוק רחוב עממי."], "Ameyoko Market": ["שוק רחוב תוסס — בגדים, קוסמטיקה, אוכל ומוצרים מקומיים.", "Ameyoko עובר לאורך פסי הרכבת בין Ueno ל-Okachimachi ומלא בחנויות קטנות ודוכנים.", "השם נקשר גם ל-'ame' של ממתקים וגם ל-'America' מתקופת השוק השחור שלאחר המלחמה.", "כיום מוכרים בו דגים, תבלינים, בגדים, נעליים, קוסמטיקה ואוכל רחוב – לא רק מזון."], "Shibuya Crossing": ["מעבר החצייה של Shibuya הוא אחד הסמלים של טוקיו המודרנית. בזמן האור הירוק הולכי רגל חוצים מכל הכיוונים בבת אחת, כשמסביב מסכי ענק, חנויות ותחנת Shibuya. הפסל של Hachiko נמצא ממש ליד וקל לשלב את שניהם באותה עצירה.", "ה-Scramble Crossing עוצר את תנועת הרכב ומאפשר להולכי רגל לחצות מכמה כיוונים בו-זמנית.", "Hachiko נמצא ליד אחת מיציאות התחנה והופך את שתי האטרקציות לעצירה אחת.", "לתצפית חינמית נבדוק את אזור Starbucks/QFRONT; אם הגישה או הישיבה השתנו, יש נקודות תצפית נוספות סביב התחנה."], "Tokyo Station / Marunouchi": ["Tokyo Station היא גם מרכז תחבורה חשוב וגם אתר בפני עצמו. חזית הלבנים האדומות בצד Marunouchi פונה לרובע עסקים מודרני ולכיוון הארמון הקיסרי; בתוך התחנה יש מתחמי אוכל, חנויות ו-Gift shops רבים.", "בניין Marunouchi האדום נפתח ב-1914 ושוחזר למראהו ההיסטורי לאחר עבודות שימור.", "הצד המזרחי של התחנה פונה ל-Yaesu, והצד המערבי ל-Marunouchi ולכיוון Imperial Palace.", "בתוך המתחם נמצאים Tokyo Character Street ו-Tokyo Ramen Street, מעבר לתפקיד התחבורתי של התחנה."], "Roppongi Hills Tokyo City View": ["Tokyo City View ב-Roppongi נותנת זווית מצוינת על מרכז טוקיו, ובמיוחד על Tokyo Tower. Roppongi עצמו משלב גורדי שחקים, אמנות, מסעדות ומתחמי קניות מודרניים.", "Tokyo City View נמצא ב-Mori Tower ומציע זווית חזקה במיוחד לכיוון Tokyo Tower ומרכז העיר.", "Roppongi Hills כולל גם את Mori Art Museum, ולכן אפשר לחבר אמנות ותצפית באותו בניין.", "זו חלופה בתשלום ל-Shibuya Sky; היתרון הוא זווית שונה ופחות תלות ב-Crossing."], "תצפית על טוקיו · אפשרויות": ["שלוש אפשרויות: Tokyo Metropolitan Government Building – חינם וללא הזמנה; Roppongi Hills Tokyo City View – תצפית מצוינת לכיוון Tokyo Tower; Shibuya Sky – נשאר כאופציה אם נרצה את החוויה האייקונית."], "חוויית במבוק Arashiyama / Okusaga": ["הרעיון ביום הזה הוא לחוות את Arashiyama כאזור ולא להפוך את יער הבמבוק המפורסם למטרה בפני עצמה. במרכז יש את Tenryu-ji, היער וגשר Togetsukyo; צפונה משם Okusaga הופכת שקטה וכפרית יותר, עם Giōji ו-Adashino Nenbutsu-ji. כך אפשר לקבל במבוק, שלכת ומקדשים בלי לבזבז זמן על המתנה לצילום ביער עמוס."]};

if ('serviceWorker' in navigator) { window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js')); }


(function(){
 const tripStart=new Date(2026,10,3), tripEnd=new Date(2026,10,17), now=new Date();
 const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 if(today>=tripStart && today<=tripEnd){
   const i=Math.round((today-tripStart)/86400000);
   setTimeout(()=>{showDay(i);const chips=document.querySelectorAll('.day-chip');if(chips[i]){chips[i].classList.add('today');const t=document.createElement('span');t.className='today-mini';t.textContent='היום';chips[i].appendChild(t)}},80);
 }
})();
